18.     .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerData.PurchaseHistory)))
19.     .Append(mlContext.Transforms.Concatenate("Features",
20.         nameof(CustomerData.Age), nameof(CustomerData.Income),
21.         nameof(CustomerData.PurchaseHistory), "RegionEncoded"))
22.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());
23. 
24. // Use TrainTestSplit when dataset is large enough (50+ rows recommended)
25. var rowCount = mlContext.Data.CreateEnumerable<CustomerData>(dataView, reuseRowObject: false).Count();
