 {
     var ctx = new MLContext(seed: 42);
     ctx.ComponentCatalog.RegisterAssembly(typeof(CustomerData).Assembly);
     var options = new Microsoft.Extensions.ML.PredictionEnginePoolOptions<CustomerData, ChurnPrediction>();
     var eng = ctx.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(model, dataView.Schema);
     return null!; // This approach won't work either
 });

 var app = builder.Build();

 app.MapGet("/", () => "Churn Predictor API — POST /predict with customer data");

 app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerData customer) =>
 {
     var prediction = pool.Predict(customer);
     return Results.Ok(new
     {
         WillChurn = prediction.PredictedLabel ? "Yes" : "No",
         Probability = prediction.Probability,
